import json
from taf.hw.hp.redfish.httpclient.ApiClient import ApiClient
from taf.hw.hp.redfish.httpclient.redfish_uri import SystemsURI


class SystemsCommon(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def get_system_info(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = SystemsURI().system_info_uri + uri_params
        return self.api_client.send_get_request(uri=uri, check_status=check_status)

    def get_integrated_management_log(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = SystemsURI().iml_log_uri + uri_params
        return self.api_client.send_get_request(uri=uri, check_status=check_status)

    def get_security_log(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = SystemsURI().sl_log_uri + uri_params
        return self.api_client.send_get_request(uri=uri, check_status=check_status)

    def get_event_log(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = SystemsURI().event_log_uri + uri_params
        return self.api_client.send_get_request(uri=uri, check_status=check_status)

    def get_storage_collection(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = SystemsURI().storage_collection_uri + uri_params
        return self.api_client.send_get_request(uri=uri, check_status=check_status)

    def get_memory_info(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = SystemsURI().memory_info_uri + uri_params
        return self.api_client.send_get_request(uri=uri, check_status=check_status)

    def get_processor_info(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = SystemsURI().processor_info_uri + uri_params
        return self.api_client.send_get_request(uri=uri, check_status=check_status)

    def get_storage_drives(self, check_status=None):
        uri_params = '?$expand=.'  # query parameters
        return self.get_storage_collection(check_status=check_status, query_parameters=uri_params)

    def clear_event_log(self, check_status=None):
        uri = SystemsURI().clear_event_uri
        data = {}
        return self.api_client.send_post_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})

    def clear_iml_log(self, check_status=None):
        uri = SystemsURI().clear_iml_uri
        data = {}
        return self.api_client.send_post_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})

    def clear_sl_log(self, check_status=None):
        uri = SystemsURI().clear_sl_uri
        data = {}
        return self.api_client.send_post_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})

    def get_boot_option_collection(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = SystemsURI().boot_option_collection_uri + uri_params
        return self.api_client.send_get_request(uri=uri, check_status=check_status)

    def get_boot_option_details(self, boot_option_id, check_status=None):
        uri = SystemsURI().boot_option_uri
        return self.api_client.send_get_request(uri=uri.format(boot_option_id=boot_option_id),
                                                check_status=check_status)

    def get_bios_attributes(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = SystemsURI().bios_attribute_uri + uri_params
        return self.api_client.send_get_request(uri=uri, check_status=check_status)

    def set_boot_option(self, new_boot_order_list, check_status=None):
        uri = SystemsURI().system_info_uri
        data = {"Boot": {"BootOrder": new_boot_order_list}}
        return self.api_client.send_patch_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})

    def set_bios_attributes(self, new_attributes_dict, check_status=None):
        uri = SystemsURI().bios_attribute_uri
        data = {"Attributes": new_attributes_dict}
        return self.api_client.send_patch_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})

    def set_host_power_status(self, reset_type, check_status=None):
        uri = SystemsURI().power_mgmt_uri
        data = {"ResetType": reset_type}
        return self.api_client.send_post_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})

    def reset_bios(self, check_status=None):
        uri = SystemsURI().reset_bios_uri
        data = {}
        return self.api_client.send_post_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})
